sys_script_include.script:
var EquipmentRequestUtil = Class.create();
EquipmentRequestUtil.prototype = {
	// Request state values (choices on the "state" field of x_2228927_equipm_0_request)
    STATE: {
        NEW: '1',
        PENDING_APPROVAL: '10',
        APPROVED: '20',
        IN_FULFILMENT: '30',
        DELIVERED: '40',
        REJECTED: '50',
        CANCELLED: '60'
    },

    // Approval tier values (choices on "approval_tier")
    TIER: {
        AUTO: 'auto',
        MANAGER: 'manager',
        MANAGER_FINANCE: 'manager_finance'
    },
    initialize: function() {
		this.managerLimit=parseFloat(gs.getProperty('x_2228927_equipm_0.manager_approval_limit','500'));
		this.financeLimit=parseFloat(gs.getProperty('x_2228927_equipm_0.finance_approval_limit', '2000'));
    },

	/**
     * Returns a plain object (not a GlideRecord) so callers can't accidentally mutate or hold on to a live record.
     * returns equipment obj or null
     */
	getEquipmentInfo:function(sysId){
		if (!sysId) {
            return null;
        }
		var equipmentRecord=new GlideRecord("x_2228927_equipm_0_equipment");
		if (!equipmentRecord.get(sysId)) {
            return null;
        }
		return{
			sys_id:equipmentRecord.getUniqueValue(),
			name:equipmentRecord.getValue('name'),
			type:equipmentRecord.getValue("type"),
			unit_cost: parseFloat(equipmentRecord.getValue('unit_cost')) || 0,
            stock_qty: parseInt(equipmentRecord.getValue('stock_qty'), 10) || 0,
            reorder_level: parseInt(equipmentRecord.getValue('reorder_level'), 10) || 0,
            active: equipmentRecord.active.toString() === 'true'
		};
	},

	/**
     * returns unit_cost * quantity (0 when equipment is unknown)
     */
	calculateTotalValue:function(equipmentSysId, quantity){
		var equipment=getEquipmentInfo(equipmentSysId);
		var qty=parseInt(quantity,10);
		if (!equipment || isNaN(qty) || qty < 1) {
            return 0;
        }
		return equipment.unit_cost*qty;
	},
	/**
     * Maps a total cost to the approval tier.
     */
    getApprovalTier: function(totalCost) {
        if (totalCost <= this.managerLimit) {
            return this.TIER.AUTO;
        }
        if (totalCost <= this.financeLimit) {
            return this.TIER.MANAGER;
        }
        return this.TIER.MANAGER_FINANCE;
    },

	hasStock: function(equipmentSysId, quantity) {
        var info = this.getEquipmentInfo(equipmentSysId);
        return !!info && info.stock_qty >= parseInt(quantity, 10);
    },

	/**
     * Decrement stock for an approved request. returns true when reserved.
     */
    reserveStock: function(equipmentSysId, quantity) {
        var qty = parseInt(quantity, 10);
        var equipment = new GlideRecord('x_2228927_equipm_0_equipment');
        if (!equipment.get(equipmentSysId)) {
            return false;
        }
        var current = parseInt(equipment.getValue('stock_qty'), 10) || 0;
        if (current < qty) {
            return false;
        }
        equipment.setValue('stock_qty', current - qty);
        return !!equipment.update();
    },

	/**
     * give stock back when an approved request is cancelled/rejected.
     */
    releaseStock: function(equipmentSysId, quantity) {
		var qty=parseInt(quantity,10);
		var equipment= new GlideRecord('x_2228927_equipm_0_equipment');
		if(!equipment.get(equipmentSysId)){
			return false;
		}
		var currentStock=parseInt(equipment.getValue('stock_qty'),10);
		equipment.setValue('stock_qty',currentStock+qty);
		return !!equipment.update();
	},

	/**
     * Is the given user allowed to see/cancel this request as the requester?
     */
    isRequester: function(requestGr, userSysId) {
        return requestGr.getValue('requested_for') === userSysId ||
            requestGr.getValue('opened_by') === userSysId;
    },

    type: 'EquipmentRequestUtil'
};
